"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import "./story.css";

export default function StoryPage() {
  const router = useRouter();
  const [story, setStory] = useState(null);

  // Երբ էջը բացվում է, կարդում ենք պահված պատմությունը
  useEffect(() => {
    const saved = sessionStorage.getItem("currentStory");
    if (saved) {
      setStory(JSON.parse(saved));
    } else {
      // Եթե պատմություն չկա, վերադարձնում ենք գլխավոր էջ
      router.push("/");
    }
  }, [router]);

  if (!story) {
    return (
      <div className="loading-screen">
        <h2>✨ Opening the book...</h2>
      </div>
    );
  }

  // ⚠️ Կարևոր է. այստեղ պետք է ճիշտ կարդալ Python-ի վերադարձրած դաշտերը
  // Ենթադրենք Python-ը վերադարձնում է `title` և `content` (կամ `story`)
  const title = story.title || `The Tale of ${story.characterName || "a Hero"}`;
  const content = story.content || story.story || story.text || JSON.stringify(story);

  return (
    <div className="story-page">
      <Link href="/" className="back-link">
        ← Back to Home
      </Link>

      <main className="story-container">
        <div className="magic-book">
          <div className="book-cover">
            <h1 className="story-title">{title}</h1>
            <p className="story-meta">
              A {story.genre} tale set in {story.world}
            </p>
          </div>

          <div className="book-pages">
            {/* Պատմությունը բաժանում ենք պարբերությունների */}
            {content.split('\n').map((paragraph, index) => (
              paragraph.trim() && <p key={index}>{paragraph}</p>
            ))}
          </div>
        </div>

        <button onClick={() => router.push("/create")} className="btn-magic">
          🪄 Write Another Tale
        </button>
      </main>
    </div>
  );
}